#!/usr/bin/env bash
set -euo pipefail

_LIB_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=bin/_agents/_lib.sh
source "$_LIB_DIR/_lib.sh"

RULES_ROOT_DIR="$1"
SKILLS_ROOT_DIR="$2"
BASE_DIR="${3:-.}"
EXCLUSIVE_ROOT_DIR="${4:-}"
# If BASE_DIR is empty (passed as ""), default to .
if [[ -z "$BASE_DIR" ]]; then
  BASE_DIR="."
fi

CLEAN="${5:-false}"

RULES_DIR="$BASE_DIR/.claude/rules"
MANIFEST="$BASE_DIR/.claude/.agentx-manifest"

# With --clean, remove files generated by the previous run (per the
# manifest) before regenerating. Hand-added files aren't in the manifest,
# so they are preserved.
if [[ "$CLEAN" == "true" ]]; then
  manifest_clean "$MANIFEST" "$BASE_DIR" "$RULES_DIR" "$BASE_DIR/.claude/skills"
fi

mkdir -p "$RULES_DIR"
manifest_init "$MANIFEST"



# Helper function to process rules
# Claude Code uses plain markdown — no frontmatter.
process_rules() {
  local src_dir="$1"

  if [[ ! -d "$src_dir" ]]; then return; fi

  while IFS= read -r -d '' rule_file; do
    local rel_path filename output_file description
    rel_path="${rule_file#"$src_dir"/}"
    # Replace slashes with underscores for the output filename
    filename="${rel_path//\//_}"
    output_file="$RULES_DIR/$filename"

    description="$(fm_field "$rule_file" description)"

    # Claude Code: plain markdown, no frontmatter
    fm_body "$rule_file" > "$output_file"
    record_generated "$MANIFEST" "$BASE_DIR" "$output_file"
  done < <(find "$src_dir" -name "*.md" -print0 | sort -z)
}

# Helper function to process skills
# Claude Code has no native skills — flatten into .claude/rules/.
process_skills() {
  local src_dir="$1"

  if [[ ! -d "$src_dir" ]]; then return; fi

  while IFS= read -r -d '' skill_file; do
    local skill_name output_dir output_file description
    skill_name="$(basename "$(dirname "$skill_file")")"
    output_dir="$BASE_DIR/.claude/skills/${skill_name}"
    output_file="$output_dir/SKILL.md"

    mkdir -p "$output_dir"

    description="$(fm_field "$skill_file" description)"

    # Claude Code: plain markdown, no frontmatter
    fm_body "$skill_file" > "$output_file"
    record_generated "$MANIFEST" "$BASE_DIR" "$output_file"
  done < <(find "$src_dir" -name "SKILL.md" -print0 | sort -z)
}

# 1. Process Core Rules
process_rules "$RULES_ROOT_DIR"

# 2. Process Core Skills
process_skills "$SKILLS_ROOT_DIR"

# 3. Process Exclusive content if provided
if [[ -n "$EXCLUSIVE_ROOT_DIR" ]] && [[ -d "$EXCLUSIVE_ROOT_DIR" ]]; then
  echo "Applying exclusive content from: $EXCLUSIVE_ROOT_DIR"
  process_rules "$EXCLUSIVE_ROOT_DIR/rules"
  process_skills "$EXCLUSIVE_ROOT_DIR/skills"
fi



echo "Claude generation complete."
